input.new_string:
void alert_lcd_boot_splash(void)
{
#ifdef __NuttX__
  /* 系统待机：深蓝底 + 顶部青条，区别于 lvgldemo widgets */
  struct fb_videoinfo_s vinfo;
  struct fb_planeinfo_s pinfo;
  int fd;
  uint16_t bg = rgb565(8, 32, 96);
  uint16_t bar = rgb565(0, 180, 210);

  if (fb_fill_color(bg, &vinfo) != 0) {
    return;
  }

  fd = open(EW_FB_DEV, O_RDWR);
  if (fd < 0) {
    printf("[alert_lcd] boot splash (ready, fill only)\n");
    return;
  }
  if (ioctl(fd, FBIOGET_PLANEINFO, (unsigned long)((uintptr_t)&pinfo)) == 0 &&
      pinfo.fbmem != NULL && pinfo.bpp == 16 && pinfo.stride > 0) {
    unsigned bar_h = vinfo.yres / 8u;
    unsigned y;
    uint8_t *base = (uint8_t *)pinfo.fbmem;
    if (bar_h < 12u) {
      bar_h = 12u;
    }
    for (y = 0; y < bar_h && y < vinfo.yres; y++) {
      uint16_t *row = (uint16_t *)(base + (size_t)y * pinfo.stride);
      unsigned x;
      for (x = 0; x < vinfo.xres; x++) {
        row[x] = bar;
      }
    }
#ifdef CONFIG_FB_UPDATE
    {
      struct fb_area_s area;
      area.x = 0;
      area.y = 0;
      area.w = vinfo.xres;
      area.h = (fb_coord_t)bar_h;
      ioctl(fd, FBIO_UPDATE, (unsigned long)((uintptr_t)&area));
    }
#endif
  }
  close(fd);
  printf("[alert_lcd] boot splash (system ready)\n");
#endif
}

input.command:
function Listen-Com($port, $baud, $sec) {
  $sp = New-Object System.IO.Ports.SerialPort $port, $baud, 'None', 8, 'One'
  $sp.DtrEnable = $false
  $sp.RtsEnable = $false
  $sp.ReadTimeout = 500
  $sp.Open()
  $b = New-Object System.Text.StringBuilder
  $end = (Get-Date).AddSeconds($sec)
  while ((Get-Date) -lt $end) {
    try { if ($sp.BytesToRead -gt 0) { [void]$b.Append($sp.ReadExisting()) } } catch {}
    Start-Sleep -Milliseconds 100
  }
  $sp.Write("`r`n")
  Start-Sleep -Seconds 1
  try { if ($sp.BytesToRead -gt 0) { [void]$b.Append($sp.ReadExisting()) } } catch {}
  $sp.Close()
  return $b.ToString()
}

Write-Host "==== 1000000 6s DTR=false ===="
$a = Listen-Com 'COM7' 1000000 6
Write-Host ("len=" + $a.Length)
if ($a.Length -gt 0) { Write-Host ($a.Substring(0, [Math]::Min(400, $a.Length))) } else { Write-Host "empty" }

Write-Host "==== 115200 6s DTR=false ===="
$b = Listen-Com 'COM7' 115200 6
Write-Host ("len=" + $b.Length)
if ($b.Length -gt 0) { Write-Host ($b.Substring(0, [Math]::Min(400, $b.Length))) } else { Write-Host "empty" }

function Listen-Dtr($dtr, $rts, $sec) {
  $sp = New-Object System.IO.Ports.SerialPort 'COM7', 1000000, 'None', 8, 'One'
  $sp.DtrEnable = $dtr
  $sp.RtsEnable = $rts
  $sp.Open()
  Write-Host "open dtr=$dtr rts=$rts"
  $b = New-Object System.Text.StringBuilder
  $end = (Get-Date).AddSeconds($sec)
  while ((Get-Date) -lt $end) {
    try { if ($sp.BytesToRead -gt 0) { [void]$b.Append($sp.ReadExisting()) } } catch {}
    Start-Sleep -Milliseconds 80
  }
  $sp.Close()
  Write-Host ("len=" + $b.Length)
  if ($b.Length -gt 0) { Write-Host ($b.ToString().Substring(0, [Math]::Min(500, $b.Length))) }
}

Listen-Dtr $true $false 10
Listen-Dtr $false $false 5
Listen-Dtr $true $true 5

