void alert_lcd_boot_splash(void)
{
#ifdef __NuttX__
#ifdef CONFIG_LV_USE_NUTTX
  /* 与 lvgldemo 相同：打开 lcd0 并循环刷新，否则 CO5300 保持全黑 */
  lv_nuttx_dsc_t info;
  lv_nuttx_result_t result;
  lv_obj_t *scr;
  lv_obj_t *bar;
  lv_obj_t *label;

  if (lv_is_initialized()) {
    printf("[alert_lcd] LVGL already up, skip boot splash\n");
    return;
  }

  lv_init();
  lv_nuttx_dsc_init(&info);
#ifdef CONFIG_LV_USE_NUTTX_LCD
  info.fb_path = "/dev/lcd0";
#endif
  lv_nuttx_init(&info, &result);
  if (result.disp == NULL) {
    printf("[alert_lcd] lv_nuttx_init failed, fallback fb fill\n");
    fb_fill_color(rgb565(8, 32, 96), NULL);
    return;
  }

  scr = lv_screen_active();
  lv_obj_set_style_bg_color(scr, lv_color_make(8, 32, 96), 0);
  lv_obj_set_style_bg_opa(scr, LV_OPA_COVER, 0);

  bar = lv_obj_create(scr);
  lv_obj_set_size(bar, LV_PCT(100), 48);
  lv_obj_align(bar, LV_ALIGN_TOP_MID, 0, 0);
  lv_obj_set_style_bg_color(bar, lv_color_make(0, 180, 210), 0);
  lv_obj_set_style_bg_opa(bar, LV_OPA_COVER, 0);
  lv_obj_set_style_border_width(bar, 0, 0);
  lv_obj_set_style_radius(bar, 0, 0);

  label = lv_label_create(scr);
  lv_label_set_text(label, "EW READY");
  lv_obj_set_style_text_color(label, lv_color_white(), 0);
  lv_obj_align(label, LV_ALIGN_CENTER, 0, 12);

  printf("[alert_lcd] boot splash LVGL (system ready)\n");
  for (;;) {
    uint32_t idle = lv_timer_handler();
    usleep((idle ? idle : 1u) * 1000u);
  }
#else
  fb_fill_color(rgb565(8, 32, 96), NULL);
  printf("[alert_lcd] boot splash (fb fallback)\n");
#endif
#endif
}

