/* ESP32 AT 猫：40P.19=PA24 TX → 模块 RX，40P.21=PA25 RX ← 模块 TX。
 * 节点默认 /dev/ttyS2（USART3，115200）。 */

#ifndef EW_WIFI_AT_DEV
#define EW_WIFI_AT_DEV "/dev/ttyS2"
#endif

int ew_wifi_at_ping(void);
int ew_wifi_at_cmd(const char *at_line);

