}
#endif

#endif

/****************************************************************************
 * UART AT 猫：PA24/PA25 → /dev/ttyS2 @ 115200
 ****************************************************************************/

#include "ew_wifi_at.h"

#include <stdio.h>
#include <string.h>
#include <errno.h>

#ifdef __NuttX__
#include <fcntl.h>
#include <unistd.h>
#include <termios.h>
#include <nuttx/config.h>
#include "bf0_hal.h"
#endif

#ifdef __NuttX__
static int g_pinmux_done;

static void wifi_uart_pinmux(void)
{
  if (g_pinmux_done) {
    return;
  }
  /* 从 SD/SPI1 复用改到 USART3，与雷达 UART2 分开。 */
  HAL_PIN_Set(PAD_PA24, USART3_TXD, PIN_PULLUP, 1);
  HAL_PIN_Set(PAD_PA25, USART3_RXD, PIN_PULLUP, 1);
  g_pinmux_done = 1;
}

static int uart_open(void)
{
  struct termios tio;
  int fd;

  wifi_uart_pinmux();
  fd = open(EW_WIFI_AT_DEV, O_RDWR | O_NOCTTY);
  if (fd < 0) {
    printf("[ew-at] open %s failed errno=%d\n", EW_WIFI_AT_DEV, errno);
    return -1;
  }

  if (tcgetattr(fd, &tio) == 0) {
    cfmakeraw(&tio);
    cfsetispeed(&tio, B115200);
    cfsetospeed(&tio, B115200);
    tio.c_cflag |= (CLOCAL | CREAD);
    tio.c_cc[VMIN] = 0;
    tio.c_cc[VTIME] = 1;
    tcsetattr(fd, TCSANOW, &tio);
  }
  tcflush(fd, TCIOFLUSH);
  return fd;
}

static int read_until(int fd, char *out, unsigned out_sz, int timeout_ms)
{
  unsigned n = 0;
  int waited = 0;

  if (out_sz == 0) {
    return -1;
  }
  out[0] = '\0';
  while (waited < timeout_ms && n + 1 < out_sz) {
    char c;
    int r = read(fd, &c, 1);
    if (r == 1) {
      out[n++] = c;
      out[n] = '\0';
      if (n >= 2 && strstr(out, "OK") != NULL) {
        return (int)n;
      }
      if (strstr(out, "ERROR") != NULL) {
        return (int)n;
      }
      waited = 0;
    } else {
      usleep(20000);
      waited += 20;
    }
  }
  return (int)n;
}

int ew_wifi_at_cmd(const char *at_line)
{
  char line[160];
  char resp[256];
  int fd;
  int n;
  size_t len;

  if (at_line == NULL || at_line[0] == '\0') {
    at_line = "AT";
  }

  snprintf(line, sizeof(line), "%s", at_line);
  len = strlen(line);
  while (len > 0 && (line[len - 1] == '\r' || line[len - 1] == '\n')) {
    line[--len] = '\0';
  }

  fd = uart_open();
  if (fd < 0) {
    return 1;
  }

  dprintf(fd, "%s\r\n", line);
  n = read_until(fd, resp, sizeof(resp), 1500);
  close(fd);

  printf("[ew-at] tx=%s\n", line);
  if (n > 0) {
    printf("[ew-at] rx=%s\n", resp);
    return (strstr(resp, "OK") != NULL) ? 0 : 2;
  }
  printf("[ew-at] no reply (check 19/21 cross, 115200, AT firmware)\n");
  return 3;
}

int ew_wifi_at_ping(void)
{
  return ew_wifi_at_cmd("AT");
}

#else

int ew_wifi_at_cmd(const char *at_line)
{
  printf("[ew-at] host stub cmd=%s\n", at_line ? at_line : "AT");
  return 0;
}

int ew_wifi_at_ping(void)
{
  return ew_wifi_at_cmd("AT");
}

#endif

