void ew_wifi_ui_tick(void)
{
  if (!g_job_done) {
    return;
  }
  g_job_done = 0;

  if (g_status != NULL) {
    lv_label_set_text(g_status, g_status_text);
  }
  if (g_job == JOB_JOIN) {
    if (ew_wifi_cred_load(g_saved_ssid, sizeof(g_saved_ssid), NULL, 0) != 0) {
      g_saved_ssid[0] = '\0';
    }
  }
  g_job = JOB_IDLE;

  if (g_scan_btn != NULL) {
    lv_obj_clear_state(g_scan_btn, LV_STATE_DISABLED);
  }
  refresh_list();
}

