  g_list = NULL;
  g_status = NULL;
  g_scan_btn = NULL;
  g_pw_layer = NULL;
  g_pw_ta = NULL;
  g_pw_title = NULL;
  memset(g_job_pass, 0, sizeof(g_job_pass));
}

