static void hw_kbd_poll(int in_chat)
{
  struct keyboard_event_s ev;
  ssize_t n;

  if (g_kbd_fd < 0) {
    return;
  }
  for (;;) {
    n = read(g_kbd_fd, &ev, sizeof(ev));
    if (n != (ssize_t)sizeof(ev)) {
      break;
    }
    if (ev.type == KEYBOARD_RELEASE) {
      if (ev.code == KEY_LEFTSHIFT || ev.code == KEY_RIGHTSHIFT) {
        g_shift = 0;
      }
      continue;
    }
    if (ev.type != KEYBOARD_PRESS) {
      continue;
    }
    if (in_chat) {
      hw_kbd_press_chat(ev.code);
    } else if (ev.code == KEYCODE_ENTER || ev.code == KEY_ENTER ||
               ev.code == KEY_ESC || ev.code == KEY_C) {
      alert_lcd_request_chat();
    }
  }
}

