/* 一帧：喂硬件按键、跑当前页逻辑、刷 LVGL */
static void page_pump(void)
{
  uint32_t idle;

  hw_kbd_poll();
  page_tick(g_page);
  idle = lv_timer_handler();
  if (idle == 0 || idle > EW_UI_FRAME_MS) {
    idle = EW_UI_FRAME_MS;
  }
  usleep(idle * 1000);
}

