#!/usr/bin/env python3
import re
import sys
import time

import serial

PORT = sys.argv[1] if len(sys.argv) > 1 else "/dev/ttyACM0"
BAUD = 1000000


def open_port():
    s = serial.Serial(PORT, BAUD, timeout=0.15)
    s.dtr = False
    s.rts = False
    return s


def drain(s, sec=0.5):
    end = time.time() + sec
    buf = bytearray()
    while time.time() < end:
        n = s.in_waiting
        if n:
            buf.extend(s.read(n))
        else:
            time.sleep(0.03)
    return bytes(buf)


def wait_prompt(s, timeout=15.0):
    buf = bytearray()
    end = time.time() + timeout
    while time.time() < end:
        n = s.in_waiting
        if n:
            buf.extend(s.read(n))
            if b"nsh>" in buf or b"nsh:" in buf:
                return bytes(buf)
        else:
            time.sleep(0.05)
    return bytes(buf)


def run(s, cmd, wait=4.0):
    drain(s, 0.2)
    s.write((cmd + "\r").encode())
    s.flush()
    time.sleep(wait)
    out = drain(s, 0.8)
    return out.decode("utf-8", "replace")


s = open_port()
s.setRTS(True)
time.sleep(0.12)
s.setRTS(False)
print("waiting boot...")
boot = wait_prompt(s, 20)
print("=== BOOT ===")
print(boot.decode("utf-8", "replace")[-3000:])

for cmd in ["help", "ew", "ew fake 10 20", "ew wifi ping", "ew wifi status"]:
    print(f"=== {cmd} ===")
    print(run(s, cmd, 5 if "wifi" in cmd else 3))

s.close()
print("OK")

