/* AT 字符串字段转义（CWJAP 参数里的 , " \ ） */
static void escape_at_field(const char *in, char *out, unsigned out_sz)
{
  unsigned j = 0;

  if (out_sz == 0) {
    return;
  }
  if (in == NULL) {
    out[0] = '\0';
    return;
  }
  for (; *in != '\0' && j + 2 < out_sz; in++) {
    if (*in == '\\' || *in == ',' || *in == '"') {
      out[j++] = '\\';
    }
    out[j++] = *in;
  }
  out[j] = '\0';
}

