int ew_wifi_scan(ew_wifi_ap_t *aps, int max)
{
  /* CWLAP 一次可回上百行，放静态区避免吃线程栈（全程持锁，无竞争） */
  static char buf[4096];
  const char *p;
  int count = 0;
  int fd;

  if (aps == NULL || max <= 0) {
    return -1;
  }

  fd = at_begin();
  if (fd < 0) {
    return -1;
  }
  if (at_wake(fd) != 0) {
    at_end(fd);
    return -1;
  }

  /* 只要 ecn/ssid/rssi 三列，回包小一半 */
  (void)at_tx(fd, "AT+CWLAPOPT=1,7", buf, sizeof(buf), 800, 1500, 0);
  (void)at_tx(fd, "AT+CWLAP", buf, sizeof(buf), 6000, 15000, 0);
  at_end(fd);

  for (p = buf; (p = strstr(p, "+CWLAP:(")) != NULL; ) {
    ew_wifi_ap_t ap;
    const char *q = p + 8;
    int i;
    int dup = 0;

    p = q;
    memset(&ap, 0, sizeof(ap));
    ap.open = (*q == '0');

    q = strchr(q, ',');
    if (q == NULL) {
      break;
    }
    q = copy_quoted(q + 1, ap.ssid, sizeof(ap.ssid));
    if (q == NULL || ap.ssid[0] == '\0') {
      continue;
    }
    if (*q != ',') {
      continue;
    }
    ap.rssi = atoi(q + 1);

    /* 同名多 AP 只留信号最强的一个 */
    for (i = 0; i < count; i++) {
      if (strcmp(aps[i].ssid, ap.ssid) == 0) {
        dup = 1;
        if (ap.rssi > aps[i].rssi) {
          aps[i] = ap;
        }
        break;
      }
    }
    if (!dup && count < max) {
      aps[count++] = ap;
    }
  }

  /* 按信号降序，条数很少，插入排序足够 */
  {
    int i;

    for (i = 1; i < count; i++) {
      ew_wifi_ap_t key = aps[i];
      int j = i - 1;

      while (j >= 0 && aps[j].rssi < key.rssi) {
        aps[j + 1] = aps[j];
        j--;
      }
      aps[j + 1] = key;
    }
  }

  printf("[ew-at] scan found %d ap\n", count);
  fflush(stdout);
  return count;
}

