static int scan_insert_ap(ew_wifi_ap_t *aps, int max, int *count, const ew_wifi_ap_t *ap)
{
  int i;

  if (ap == NULL || ap->ssid[0] == '\0') {
    return 0;
  }
  for (i = 0; i < *count; i++) {
    if (strcmp(aps[i].ssid, ap->ssid) == 0) {
      if (ap->rssi > aps[i].rssi) {
        aps[i] = *ap;
      }
      return 0;
    }
  }
  if (*count >= max) {
    return 0;
  }
  aps[*count] = *ap;
  (*count)++;
  return 0;
}

static int scan_parse_line(const char *line, ew_wifi_ap_t *ap)
{
  const char *p;
  const char *q;

  if (line == NULL || ap == NULL) {
    return -1;
  }
  p = strstr(line, "+CWLAP:(");
  if (p == NULL) {
    return -1;
  }
  q = p + 8;
  memset(ap, 0, sizeof(*ap));
  ap->open = (*q == '0');
  q = strchr(q, ',');
  if (q == NULL) {
    return -1;
  }
  q = copy_quoted(q + 1, ap->ssid, sizeof(ap->ssid));
  if (q == NULL || ap->ssid[0] == '\0' || *q != ',') {
    return -1;
  }
  ap->rssi = atoi(q + 1);
  return 0;
}

static void scan_sort_rssi(ew_wifi_ap_t *aps, int count)
{
  int i;

  for (i = 1; i < count; i++) {
    ew_wifi_ap_t key = aps[i];
    int j = i - 1;

    while (j >= 0 && aps[j].rssi < key.rssi) {
      aps[j + 1] = aps[j];
      j--;
    }
    aps[j + 1] = key;
  }
}

/* 逐行解析 CWLAP，不受固定 rx 缓冲长度限制 */
static int scan_collect(int fd, ew_wifi_ap_t *aps, int max)
{
  char line[192];
  unsigned li = 0;
  int idle = 0;
  int spent = 0;
  int count = 0;

  while (idle < 8000 && spent < 22000) {
    char c;
    ssize_t r = read(fd, &c, 1);

    if (r == 1) {
      idle = 0;
      if (c == '\r') {
        continue;
      }
      if (c == '\n' || li + 1 >= sizeof(line)) {
        ew_wifi_ap_t ap;

        line[li] = '\0';
        li = 0;
        if (line[0] == '\0') {
          continue;
        }
        if (strcmp(line, "OK") == 0) {
          break;
        }
        if (scan_parse_line(line, &ap) == 0) {
          scan_insert_ap(aps, max, &count, &ap);
        }
        continue;
      }
      line[li++] = c;
    } else {
      usleep(20000);
      idle += 20;
      spent += 20;
    }
  }
  scan_sort_rssi(aps, count);
  return count;
}

int ew_wifi_scan(ew_wifi_ap_t *aps, int max)
{
  char opt_resp[256];
  char tx[16];
  int count = 0;
  int fd;
  int m;

  if (aps == NULL || max <= 0) {
    return -1;
  }

  fd = at_begin();
  if (fd < 0) {
    return -1;
  }
  if (at_wake(fd) != 0) {
    at_end(fd);
    return -1;
  }

  /* ecn + ssid + rssi，缩短每行 */
  (void)at_tx(fd, "AT+CWLAPOPT=1,7", opt_resp, sizeof(opt_resp), 800, 1500, 0);
  m = snprintf(tx, sizeof(tx), "AT+CWLAP");
  if (m > 0) {
    (void)write_all(fd, tx, (unsigned)m);
    (void)write_all(fd, "\r\n", 2);
  }
  printf("[ew-at] tx=AT+CWLAP\n");
  fflush(stdout);

  count = scan_collect(fd, aps, max);
  at_end(fd);

  printf("[ew-at] scan found %d ap\n", count);
  fflush(stdout);
  return count;
}

