static int scan_parse_line(const char *line, ew_wifi_ap_t *ap)
{
  const char *p;
  const char *q;

  if (line == NULL || ap == NULL) {
    return -1;
  }
  p = strstr(line, "+CWLAP:(");
  if (p == NULL) {
    return -1;
  }
  q = p + 8;
  memset(ap, 0, sizeof(ap));
  ap->open = (*q == '0');
  q = strchr(q, ',');
  if (q == NULL) {
    return -1;
  }
  q = copy_quoted(q + 1, ap->ssid, sizeof(ap->ssid));
  if (q == NULL || ap->ssid[0] == '\0' || *q != ',') {
    return -1;
  }
  ap->rssi = atoi(q + 1);
  return 0;
}

input.new_string:
/* 解析一行 +CWLAP（兼容带/不带括号、CWLAPOPT 裁剪字段） */
static int scan_parse_line(const char *line, ew_wifi_ap_t *ap)
{
  const char *p;
  const char *q;

  if (line == NULL || ap == NULL) {
    return -1;
  }
  p = strstr(line, "+CWLAP:");
  if (p == NULL) {
    return -1;
  }
  p += 7;
  if (*p == '(') {
    p++;
  }
  memset(ap, 0, sizeof(ap));
  ap->open = (*p == '0');
  q = strchr(p, ',');
  if (q == NULL) {
    return -1;
  }
  q = copy_quoted(q + 1, ap->ssid, sizeof(ap->ssid));
  if (q == NULL || *q != ',') {
    return -1;
  }
  ap->rssi = atoi(q + 1);
  if (ap->ssid[0] == '\0') {
    snprintf(ap->ssid, sizeof(ap->ssid), "[hidden]");
  }
  return 0;
}

static int scan_from_buf(const char *buf, ew_wifi_ap_t *aps, int max, int *count)
{
  const char *p;

  if (buf == NULL || aps == NULL || count == NULL) {
    return -1;
  }
  for (p = buf; (p = strstr(p, "+CWLAP:")) != NULL; ) {
    ew_wifi_ap_t ap;
    const char *eol = strchr(p, '\n');

    if (scan_parse_line(p, &ap) == 0) {
      scan_insert_ap(aps, max, count, &ap);
    }
    p = (eol != NULL) ? eol + 1 : p + 7;
  }
  return *count;
}

