/* CWLAP 专用：见到 OK 后继续读到静默，避免异步回包被截断 */
static int at_read_scan(int fd, char *out, unsigned out_sz, int total_ms)
{
  unsigned n = 0;
  int idle = 0;
  int spent = 0;
  int saw_ok = 0;

  if (out_sz == 0) {
    return -1;
  }
  out[0] = '\0';
  while (spent < total_ms) {
    char chunk[128];
    ssize_t r = read(fd, chunk, sizeof(chunk));

    if (r > 0) {
      unsigned take = (unsigned)r;
      unsigned off = 0;

      idle = 0;
      while (off < take) {
        if (n + 1 < out_sz) {
          unsigned room = out_sz - n - 1;
          unsigned part = take - off;

          if (part > room) {
            part = room;
          }
          memcpy(out + n, chunk + off, part);
          n += part;
          out[n] = '\0';
          off += part;
        } else {
          off = take;
        }
      }
      if (resp_ok(out)) {
        saw_ok = 1;
      }
    } else {
      usleep(20000);
      spent += 20;
      idle += 20;
      if (saw_ok && idle >= 3000) {
        break;
      }
      if (!saw_ok && idle >= 15000) {
        break;
      }
    }
  }
  return (int)n;
}

static int scan_count_markers(const char *buf)
{
  const char *p = buf;
