static lv_obj_t *ctl_hit_obj(lv_obj_t *root, lv_point_t *pt)
{
  lv_obj_t *child;
  uint32_t i;
  uint32_t n;

  if (root == NULL) {
    return NULL;
  }
  n = lv_obj_get_child_count(root);
  for (i = n; i > 0; i--) {
    child = lv_obj_get_child(root, i - 1);
    child = ctl_hit_obj(child, pt);
    if (child != NULL) {
      return child;
    }
  }
  if (lv_obj_hit_test(root, pt)) {
    return root;
  }
  return NULL;
}

